with shape as (-- Read-only stable metadata, no row data or credentials. Names, not database-local OIDs.
select jsonb_build_object(
 'relations', coalesce((select jsonb_agg(jsonb_build_object(
  'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
  'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type),'[]') from aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 's'::"char" else 'r'::"char" end,c.relowner))) a),
  'columns',(select coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) order by a.attnum),'[]') from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',(select coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid),k.convalidated,k.condeferrable,k.condeferred) order by k.conname),'[]') from pg_constraint k where k.conrelid=c.oid),
  'triggers',(select coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) order by t.tgname),'[]') from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
  'policies',(select count(*) from pg_policy p where p.polrelid=c.oid)
 ) order by c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relname like 'hardware_%'),'[]'),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),
 'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type),'[]') from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) order by p.oid::regprocedure::text) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like 'hardware_%'),'[]')
)) select case when jsonb_build_object=$reviewed${"functions":[{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_checkout_get(text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_checkout_get(p_client text, p_guest_hash text, p_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\n select jsonb_build_object('id',o.id,'order_state',o.order_state,'payment_eligible',false,'goods_total_kobo',o.goods_total_kobo,'goods_tax_kobo',o.goods_tax_kobo,'delivery_total_kobo',o.delivery_total_kobo,'payable_total_kobo',o.payable_total_kobo)\n from hardware_orders o join hardware_checkout_receipts r on r.order_id=o.id where o.id=p_id and r.client=p_client and r.guest_hash=p_guest_hash\n$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_checkout_quote(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.hardware_checkout_quote(p_lines jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare v catalogue_variants%rowtype; p catalogue_products%rowtype; item jsonb; content jsonb; lines jsonb:='[]'; line jsonb; pc uuid;\n q integer; pos integer:=0; gross bigint; tax bigint; total bigint:=0; taxes bigint:=0; result jsonb;\nbegin\n if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 50 then raise exception 'invalid_order_lines' using errcode='PT400'; end if;\n -- Lock products before variants, matching catalogue edit order; requests use stable ID ordering.\n perform cp.id from catalogue_products cp where cp.id in\n (select cv.product_id from catalogue_variants cv join jsonb_array_elements(p_lines) x on cv.id::text=x->>'variant_id') order by cp.id for share;\n for item in select value from jsonb_array_elements(p_lines) order by value->>'variant_id' loop\n if jsonb_typeof(item) is distinct from 'object' or item-array['variant_id','quantity']<>'{}'::jsonb\n or jsonb_typeof(item->'quantity') is distinct from 'number' or (item->>'quantity') !~ '^[0-9]{1,4}$' then raise exception 'invalid_order_lines' using errcode='PT400'; end if;\n q:=(item->>'quantity')::integer; if q not between 1 and 1000 then raise exception 'invalid_quantity' using errcode='PT400'; end if;\n begin select * into v from catalogue_variants where id=(item->>'variant_id')::uuid for share;\n exception when invalid_text_representation then raise exception 'invalid_variant' using errcode='PT400'; end;\n if v.id is null or v.status<>'active' or v.sourcing='discontinued' then raise exception 'variant_unavailable' using errcode='PT409'; end if;\n if exists(select 1 from jsonb_array_elements(lines) x where x->>'variant_id'=v.id::text) then raise exception 'duplicate_variant' using errcode='PT400'; end if;\n select * into p from catalogue_products where id=v.product_id for share;\n perform 1 from catalogue_public_listings where product_id=p.id and status='public' and public_version=p.published_version for share;\n if not found then raise exception 'product_unavailable' using errcode='PT409'; end if;\n if v.sourcing<>'in_stock' or v.stock_on_hand-v.stock_reserved<q then raise exception 'stock_unavailable' using errcode='PT409'; end if;\n if p.publication_status<>'published' or p.published_version is null or not exists(select 1 from catalogue_reviews r where r.product_id=p.id and r.version=p.published_version and r.decision='approved') then raise exception 'product_not_approved' using errcode='PT409'; end if;\n select pv.content into content from catalogue_product_versions pv where product_id=p.id and version=p.published_version;\n if not exists(select 1 from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku) then raise exception 'variant_not_published' using errcode='PT409'; end if;\n select x.id into pc from catalogue_price_changes x where x.variant_id=v.id and x.new_price_ngn_kobo=v.price_ngn_kobo\n and x.new_vat_treatment=v.vat_treatment and x.new_vat_rate_bp=v.vat_rate_bp\n and exists(select 1 from catalogue_price_decisions a where a.price_change_id=x.id and a.decision='approved' and a.actor<>x.requested_by)\n and exists(select 1 from catalogue_price_decisions b where b.price_change_id=x.id and b.decision='published') order by x.requested_at desc,x.id limit 1;\n if pc is null or v.price_ngn_kobo is null or v.price_ngn_kobo not between 1 and 900000000 then raise exception 'price_not_verified' using errcode='PT409'; end if;\n gross:=v.price_ngn_kobo*q; tax:=round(gross::numeric*v.vat_rate_bp/(10000+v.vat_rate_bp))::bigint;\n total:=total+gross; taxes:=taxes+tax; pos:=pos+1;\n line:=jsonb_build_object('position',pos,'product_id',p.id,'product_version',p.published_version,'variant_id',v.id,'variant_row_version',v.row_version,'price_change_id',pc,\n 'sku',v.sku,'product_name',content->>'name','variant_name',(select x->>'name' from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku limit 1),\n 'variant_options',coalesce((select x->'options' from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku limit 1),'{}'::jsonb),\n 'quantity',q,'unit_price_kobo',v.price_ngn_kobo,'vat_treatment',v.vat_treatment,'vat_rate_bp',v.vat_rate_bp,'gross_kobo',gross,'tax_kobo',tax,\n 'sourcing',v.sourcing,'availability_at_creation',case when v.sourcing='in_stock' and v.stock_on_hand-v.stock_reserved>=q then 'in_stock' else 'confirmation_required' end);\n lines:=lines||jsonb_build_array(line);\n end loop;\n if total>900000000000 then raise exception 'order_total_limit' using errcode='PT400'; end if;\n\n result:=jsonb_build_object('lines',lines,'goods_total_kobo',total,'goods_tax_kobo',taxes,'delivery_total_kobo',null,'payable_total_kobo',null,'payment_eligible',false);\n return result||jsonb_build_object('quote_hash',encode(sha256(convert_to(result::text,'UTF8')),'hex'));\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_checkout_submit(text,text,text,jsonb,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_checkout_submit(p_client text, p_guest_hash text, p_key text, p_request jsonb, p_quote_hash text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare r hardware_checkout_receipts%rowtype; h text; actor text; quote jsonb; customer jsonb; d jsonb; cid uuid; opid uuid; oid uuid;\nbegin\n if p_client is null or p_client !~ '^[a-zA-Z0-9_-]{1,80}$' or p_guest_hash is null or p_guest_hash !~ '^[0-9a-f]{64}$' or p_key is null or p_key !~ '^[A-Za-z0-9_-]{16,128}$'\n or jsonb_typeof(p_request) is distinct from 'object' or p_request-array['customer','delivery','installation_requested','lines']<>'{}' then raise exception 'invalid_checkout' using errcode='PT400'; end if;\n h:=encode(sha256(convert_to(p_request::text,'UTF8')),'hex'); actor:='checkout:'||p_client;\n perform pg_advisory_xact_lock(hashtextextended(p_client||':'||p_guest_hash||':'||p_key,0));\n select * into r from hardware_checkout_receipts where client=p_client and guest_hash=p_guest_hash and idempotency_key=p_key;\n if found then\n if r.request_hash<>h then raise exception 'idempotency_conflict' using errcode='PT409'; end if;\n return jsonb_build_object('id',r.order_id,'replayed',true,'payment_eligible',false); end if;\n customer:=p_request->'customer'; d:=p_request->'delivery';\n if jsonb_typeof(customer) is distinct from 'object' or customer-array['name','email','phone']<>'{}'\n or exists(select 1 from jsonb_each(customer) x where jsonb_typeof(x.value)<>'string')\n or coalesce(length(trim(customer->>'name')),0) not between 2 and 160\n or coalesce(customer->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\\.[^[:space:]@]+$' or length(customer->>'email')>254\n or coalesce(customer->>'phone','') !~ '^[+0-9 ()-]{7,30}$' then raise exception 'invalid_customer' using errcode='PT400'; end if;\n if jsonb_typeof(d) is distinct from 'object' or d-array['country','state','city','address','postcode']<>'{}' or d->>'country' is distinct from 'NG'\n or coalesce(d->>'state','')<>all(array['Abia','Adamawa','Akwa Ibom','Anambra','Bauchi','Bayelsa','Benue','Borno','Cross River','Delta','Ebonyi','Edo','Ekiti','Enugu','FCT','Gombe','Imo','Jigawa','Kaduna','Kano','Katsina','Kebbi','Kogi','Kwara','Lagos','Nasarawa','Niger','Ogun','Ondo','Osun','Oyo','Plateau','Rivers','Sokoto','Taraba','Yobe','Zamfara'])\n or exists(select 1 from jsonb_each(d) x where jsonb_typeof(x.value)<>'string' or length(x.value#>>'{}')>500)\n or coalesce(length(trim(d->>'city')),0) not between 1 and 120 or coalesce(length(trim(d->>'address')),0) not between 5 and 500\n or jsonb_typeof(p_request->'installation_requested') is distinct from 'boolean' then raise exception 'delivery_restricted' using errcode='PT400'; end if;\n quote:=hardware_checkout_quote(p_request->'lines');\n if p_quote_hash is distinct from quote->>'quote_hash' then raise exception 'price_changed' using errcode='PT409'; end if;\n -- Unverified guest contact details never merge into or overwrite an existing CRM customer by email.\n insert into crm_contacts(name,email,phone,source,metadata) values(trim(customer->>'name'),lower(trim(customer->>'email')),trim(customer->>'phone'),'getoyi_checkout',jsonb_build_object('identity_verified',false)) returning id into cid;\n insert into crm_opportunities(contact_id,business_unit,inquiry_type,pipeline,source,metadata) values(cid,'getoyi','hardware_order','corporate','getoyi_checkout',jsonb_build_object('payment_eligible',false,'installation_requested',p_request->'installation_requested')) returning id into opid;\n insert into hardware_orders(contact_id,opportunity_id,created_by,idempotency_key,request_hash,goods_total_kobo,goods_tax_kobo,installation_requested)\n values(cid,opid,actor,encode(sha256(convert_to(p_guest_hash||':'||p_key,'UTF8')),'hex'),h,(quote->>'goods_total_kobo')::bigint,(quote->>'goods_tax_kobo')::bigint,(p_request->>'installation_requested')::boolean) returning id into oid;\n insert into hardware_order_private values(oid,customer,d);\n insert into hardware_order_lines select oid,x.* from jsonb_to_recordset(quote->'lines') as x(position integer,product_id uuid,product_version integer,variant_id uuid,variant_row_version integer,price_change_id uuid,sku text,product_name text,variant_name text,variant_options jsonb,quantity integer,unit_price_kobo bigint,vat_treatment text,vat_rate_bp integer,gross_kobo bigint,tax_kobo bigint,sourcing text,availability_at_creation text);\n insert into hardware_order_events(order_id,event_type,row_version,actor,metadata) values(oid,'created',1,actor,jsonb_build_object('payment_eligible',false,'source','getoyi_checkout'));\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(actor,'hardware_order_created','hardware_order',oid::text,jsonb_build_object('row_version',1,'payment_eligible',false,'source','getoyi_checkout'));\n insert into crm_activities(contact_id,opportunity_id,related_type,related_id,activity_type,title,source,actor,metadata) values(cid,opid,'hardware_order',oid::text,'hardware_order_created','Hardware order awaiting confirmation','getoyi_checkout',actor,jsonb_build_object('order_id',oid,'payment_eligible',false));\n insert into hardware_checkout_receipts(client,guest_hash,idempotency_key,request_hash,order_id) values(p_client,p_guest_hash,p_key,h,oid);\n return jsonb_build_object('id',oid,'replayed',false,'payment_eligible',false);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_financial_list(text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_financial_list(p_actor text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$begin\n perform hardware_order_require_actor(p_actor,'commerce.orders.read');\n return coalesce((select jsonb_agg(to_jsonb(x)) from (select o.id,o.payment_state,o.order_state,o.payable_total_kobo,\n (select state from hardware_financial_observations f where f.order_id=o.id order by event_id desc limit 1) financial_state,\n (select to_jsonb(r)||jsonb_build_object('approved_by',(select approved_by from hardware_refund_decisions where request_id=r.id)) from hardware_refund_requests r where r.order_id=o.id) refund,\n (select coalesce(jsonb_agg(to_jsonb(h) order by h.created_at),'[]') from hardware_payment_history h where h.order_id=o.id) history\n from hardware_orders o order by o.created_at desc limit 100) x),'[]');end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_financial_note(text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_financial_note(p_actor text, p_order uuid, p_note text)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$begin\n perform hardware_order_require_actor(p_actor,'commerce.orders.reconcile');\n if length(p_note) not between 8 and 500 or p_note is null then raise exception 'invalid_reconciliation_note' using errcode='PT400';end if;\n perform 1 from hardware_orders where id=p_order;if not found then raise exception 'order_not_found' using errcode='PT404';end if;\n perform hardware_payment_log(p_order,'reconciliation_note',p_actor,jsonb_build_object('note',p_note));end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_financial_notify()","definition":"CREATE OR REPLACE FUNCTION public.hardware_financial_notify()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare oid uuid;actor text;begin\n if tg_table_name='hardware_refund_requests' then\n oid:=new.order_id;actor:=new.requested_by;\n insert into notifications(type,reason,summary,recipient_email,related_type,related_id,metadata)\n select 'internal','hardware_refund_review','Hardware refund requires independent review',email,'hardware_order',oid::text,jsonb_build_object('request_id',new.id)\n from admin_users where status='active' and removed_at is null and lower(email)<>actor and (role='super_admin' or 'commerce.orders.refund.approve'=any(permission_scopes));\n elsif tg_table_name='hardware_refund_decisions' then\n select order_id,requested_by into oid,actor from hardware_refund_requests where id=new.request_id;\n if actor=new.approved_by then raise exception 'self_approval_denied' using errcode='PT403';end if;\n insert into notifications(type,reason,summary,recipient_email,related_type,related_id) values('internal','hardware_refund_approved','Refund approved for provider processing',actor,'hardware_order',oid::text);\n end if;return new;end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_financial_observe(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.hardware_financial_observe(p jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare a hardware_payment_authorizations%rowtype;h text;oldrow hardware_financial_observations%rowtype;begin\n select * into a from hardware_payment_authorizations where reference=p->>'reference';\n if not found or a.order_id::text is distinct from p->>'order_id' or a.amount_kobo::text is distinct from p->>'amount_kobo' or p->>'environment' is distinct from 'test' then raise exception 'financial_evidence_mismatch' using errcode='PT409';end if;\n if p->>'state'='refund_processed' and not exists(select 1 from hardware_refund_requests r join hardware_refund_decisions d on d.request_id=r.id join hardware_payment_confirmations c on c.reference=r.reference where r.id::text=p->'evidence'->>'approval_id' and r.order_id=a.order_id and r.amount_kobo::text=p->'evidence'->>'amount_kobo' and c.provider_id=p->'evidence'->>'transaction_id' and p->'evidence'->>'status'='processed' and p->'evidence'->>'currency'='NGN' and p->'evidence'->>'environment'='test' and p->'evidence'->>'refund_id' ~ '^[0-9]+$') then raise exception 'verified_refund_required' using errcode='PT409';end if;\n h:=encode(sha256(convert_to(p::text,'UTF8')),'hex');\n insert into hardware_financial_observations values((p->>'event_id')::bigint,a.order_id,a.reference,p->>'state',p->'evidence',h,now()) on conflict do nothing;\n select * into oldrow from hardware_financial_observations where event_id=(p->>'event_id')::bigint;\n if oldrow.fingerprint<>h then raise exception 'financial_replay_conflict' using errcode='PT409';end if;\n if not exists(select 1 from hardware_payment_history where order_id=a.order_id and detail->>'financial_event_id'=p->>'event_id') then perform hardware_payment_log(a.order_id,'financial_observed','backend:hardware_payments',jsonb_build_object('financial_event_id',p->>'event_id','state',p->>'state'));end if;\nend$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_financial_previous_quote(text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_financial_previous_quote(p_client text, p_guest_hash text, p_order uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare o hardware_orders%rowtype;d hardware_payment_delivery%rowtype;r hardware_reservations%rowtype;begin\n if hardware_checkout_get(p_client,p_guest_hash,p_order) is null then raise exception 'order_not_found' using errcode='PT404';end if;\n perform pg_advisory_xact_lock(71404,4);\n select * into o from hardware_orders where id=p_order for update;select * into d from hardware_payment_delivery where order_id=p_order;select * into r from hardware_reservations where order_id=p_order;\n return jsonb_build_object('order_id',o.id,'amount_kobo',o.payable_total_kobo,'goods_tax_kobo',o.goods_tax_kobo,'delivery_kobo',d.gross_kobo,'delivery_tax_kobo',d.tax_kobo,'payment_state',o.payment_state,'eligible',o.order_state='awaiting_confirmation' and o.payment_state='not_started' and d.order_id is not null and r.state='held' and r.expires_at>clock_timestamp() and hardware_payment_eligible(p_order));end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_cancel(text,uuid,integer)","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_cancel(p_actor text, p_id uuid, p_expected integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare o hardware_orders%rowtype; result jsonb;\nbegin\n perform hardware_order_require_actor(p_actor,'commerce.orders.cancel');perform pg_advisory_xact_lock(71404,4);\n select * into o from hardware_orders where id=p_id for update;\n if not found then raise exception 'order_not_found' using errcode='PT404';end if;\n if o.reservation_state='allocated' then raise exception 'allocated_order_requires_refund_workflow' using errcode='PT409';end if;\n if o.row_version<>p_expected and not (o.order_state='cancelled' and o.row_version=p_expected+1) then raise exception 'order_state_changed' using errcode='PT409';end if;\n perform hardware_reservation_finish(p_id,'released',p_actor,'Order cancelled');\n result:=hardware_reservation_cancel_core(p_actor,p_id,p_expected);return result;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_consistency()","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_consistency()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare oid uuid; o hardware_orders%rowtype; n integer; gross bigint; tax bigint;\nbegin\n oid:=coalesce((to_jsonb(new)->>'order_id')::uuid,(to_jsonb(new)->>'id')::uuid);\n select * into o from hardware_orders where id=oid;\n select count(*),sum(gross_kobo),sum(tax_kobo) into n,gross,tax from hardware_order_lines where order_id=oid;\n if n not between 1 and 50 or gross is distinct from o.goods_total_kobo or tax is distinct from o.goods_tax_kobo\n or not exists(select 1 from hardware_order_private where order_id=oid)\n or (select count(*) from hardware_order_events where order_id=oid)<>o.row_version\n or not exists(select 1 from hardware_order_events where order_id=oid and row_version=1 and event_type='created' and actor=o.created_by)\n or (o.order_state='cancelled' and not exists(select 1 from hardware_order_events where order_id=oid and row_version=o.row_version and event_type='cancelled'))\n or exists(select 1 from hardware_order_events e where e.order_id=oid and (not exists(select 1 from audit_events a where a.target_type='hardware_order' and a.target_id=oid::text and a.action='hardware_order_'||e.event_type and a.actor_email=e.actor and (a.metadata->>'row_version')::integer=e.row_version)\n or not exists(select 1 from crm_activities a where a.related_type='hardware_order' and a.related_id=oid::text and a.activity_type='hardware_order_'||e.event_type and a.actor=e.actor and a.contact_id=o.contact_id)))\n or exists(select 1 from hardware_order_lines l join catalogue_variants v on v.id=l.variant_id where l.order_id=oid and (l.product_id<>v.product_id or l.sku<>v.sku or l.tax_kobo<>round(l.gross_kobo::numeric*l.vat_rate_bp/(10000+l.vat_rate_bp))::bigint)) then\n raise exception 'order_integrity_violation' using errcode='PT409'; end if;\n return null;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_create(text,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_create(p_actor text, p_key text, p_request jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare o hardware_orders%rowtype; c crm_contacts%rowtype; v catalogue_variants%rowtype; p catalogue_products%rowtype;\n item jsonb; content jsonb; lines jsonb:='[]'; line jsonb; d jsonb; h text; pc uuid; cid uuid; oid uuid; opid uuid;\n q integer; pos integer:=0; gross bigint; tax bigint; total bigint:=0; taxes bigint:=0;\nbegin\n perform hardware_order_require_actor(p_actor,'commerce.orders.create');\n perform hardware_order_require_actor(p_actor,'crm.read');\n if p_key is null or p_key !~ '^[A-Za-z0-9_-]{16,128}$' or jsonb_typeof(p_request) is distinct from 'object' or\n (p_request-array['contact_id','organization_id','opportunity_id','delivery','installation_requested','lines'])<>'{}'::jsonb then\n raise exception 'invalid_order_input' using errcode='PT400'; end if;\n h:=encode(sha256(convert_to(p_request::text,'UTF8')),'hex');\n -- Serialize same actor/key before looking at changing catalogue state; successful retries return the same order.\n perform pg_advisory_xact_lock(hashtextextended(p_actor||':'||p_key,0));\n select * into o from hardware_orders where created_by=p_actor and idempotency_key=p_key;\n if found then\n if o.request_hash<>h then raise exception 'idempotency_conflict' using errcode='PT409'; end if;\n return jsonb_build_object('id',o.id,'replayed',true); end if;\n begin cid:=(p_request->>'contact_id')::uuid; oid:=(p_request->>'organization_id')::uuid; opid:=(p_request->>'opportunity_id')::uuid;\n exception when invalid_text_representation then raise exception 'invalid_crm_reference' using errcode='PT400'; end;\n select * into c from crm_contacts where id=cid for share;\n if not found or (oid is not null and c.organization_id is distinct from oid) then raise exception 'invalid_crm_reference' using errcode='PT400'; end if;\n oid:=coalesce(oid,c.organization_id);\n if opid is not null and not exists(select 1 from crm_opportunities where id=opid and contact_id=cid and organization_id is not distinct from oid) then\n raise exception 'invalid_crm_reference' using errcode='PT400'; end if;\n d:=p_request->'delivery';\n if jsonb_typeof(d) is distinct from 'object' or (d-array['country','state','city','address','postcode'])<>'{}'::jsonb\n or d->>'country' is distinct from 'NG' or exists(select 1 from jsonb_each(d) x where jsonb_typeof(x.value)<>'string' or length(x.value#>>'{}')>500)\n or coalesce(length(trim(d->>'state')),0)=0 or coalesce(length(trim(d->>'city')),0)=0 or coalesce(length(trim(d->>'address')),0)=0\n or (p_request ? 'installation_requested' and jsonb_typeof(p_request->'installation_requested')<>'boolean') then raise exception 'invalid_delivery' using errcode='PT400'; end if;\n if jsonb_typeof(p_request->'lines') is distinct from 'array' or jsonb_array_length(p_request->'lines') not between 1 and 50 then raise exception 'invalid_order_lines' using errcode='PT400'; end if;\n -- Lock products before variants, matching catalogue edit order; requests use stable ID ordering.\n perform cp.id from catalogue_products cp where cp.id in\n (select cv.product_id from catalogue_variants cv join jsonb_array_elements(p_request->'lines') x on cv.id::text=x->>'variant_id') order by cp.id for share;\n for item in select value from jsonb_array_elements(p_request->'lines') order by value->>'variant_id' loop\n if jsonb_typeof(item) is distinct from 'object' or item-array['variant_id','quantity']<>'{}'::jsonb\n or jsonb_typeof(item->'quantity') is distinct from 'number' or (item->>'quantity') !~ '^[0-9]{1,4}$' then raise exception 'invalid_order_lines' using errcode='PT400'; end if;\n q:=(item->>'quantity')::integer; if q not between 1 and 1000 then raise exception 'invalid_quantity' using errcode='PT400'; end if;\n begin select * into v from catalogue_variants where id=(item->>'variant_id')::uuid for share;\n exception when invalid_text_representation then raise exception 'invalid_variant' using errcode='PT400'; end;\n if v.id is null or v.status<>'active' or v.sourcing='discontinued' then raise exception 'variant_unavailable' using errcode='PT409'; end if;\n if exists(select 1 from jsonb_array_elements(lines) x where x->>'variant_id'=v.id::text) then raise exception 'duplicate_variant' using errcode='PT400'; end if;\n select * into p from catalogue_products where id=v.product_id for share;\n if p.publication_status<>'published' or p.published_version is null or not exists(select 1 from catalogue_reviews r where r.product_id=p.id and r.version=p.published_version and r.decision='approved') then raise exception 'product_not_approved' using errcode='PT409'; end if;\n select pv.content into content from catalogue_product_versions pv where product_id=p.id and version=p.published_version;\n if not exists(select 1 from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku) then raise exception 'variant_not_published' using errcode='PT409'; end if;\n select x.id into pc from catalogue_price_changes x where x.variant_id=v.id and x.new_price_ngn_kobo=v.price_ngn_kobo\n and x.new_vat_treatment=v.vat_treatment and x.new_vat_rate_bp=v.vat_rate_bp\n and exists(select 1 from catalogue_price_decisions a where a.price_change_id=x.id and a.decision='approved' and a.actor<>x.requested_by)\n and exists(select 1 from catalogue_price_decisions b where b.price_change_id=x.id and b.decision='published') order by x.requested_at desc,x.id limit 1;\n if pc is null or v.price_ngn_kobo is null or v.price_ngn_kobo not between 1 and 900000000 then raise exception 'price_not_verified' using errcode='PT409'; end if;\n gross:=v.price_ngn_kobo*q; tax:=round(gross::numeric*v.vat_rate_bp/(10000+v.vat_rate_bp))::bigint;\n total:=total+gross; taxes:=taxes+tax; pos:=pos+1;\n line:=jsonb_build_object('position',pos,'product_id',p.id,'product_version',p.published_version,'variant_id',v.id,'variant_row_version',v.row_version,'price_change_id',pc,\n 'sku',v.sku,'product_name',content->>'name','variant_name',(select x->>'name' from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku limit 1),\n 'variant_options',coalesce((select x->'options' from jsonb_array_elements(content->'variants') x where x->>'sku'=v.sku limit 1),'{}'::jsonb),\n 'quantity',q,'unit_price_kobo',v.price_ngn_kobo,'vat_treatment',v.vat_treatment,'vat_rate_bp',v.vat_rate_bp,'gross_kobo',gross,'tax_kobo',tax,\n 'sourcing',v.sourcing,'availability_at_creation',case when v.sourcing='in_stock' and v.stock_on_hand-v.stock_reserved>=q then 'in_stock' else 'confirmation_required' end);\n lines:=lines||jsonb_build_array(line);\n end loop;\n if total>900000000000 then raise exception 'order_total_limit' using errcode='PT400'; end if;\n insert into hardware_orders(contact_id,organization_id,opportunity_id,created_by,idempotency_key,request_hash,goods_total_kobo,goods_tax_kobo,installation_requested)\n values(cid,oid,opid,p_actor,p_key,h,total,taxes,coalesce((p_request->>'installation_requested')::boolean,false)) returning * into o;\n insert into hardware_order_private values(o.id,jsonb_strip_nulls(jsonb_build_object('name',c.name,'email',c.email,'phone',c.phone)),d);\n insert into hardware_order_lines select o.id,x.* from jsonb_to_recordset(lines) as x(position integer,product_id uuid,product_version integer,variant_id uuid,variant_row_version integer,price_change_id uuid,sku text,product_name text,variant_name text,variant_options jsonb,quantity integer,unit_price_kobo bigint,vat_treatment text,vat_rate_bp integer,gross_kobo bigint,tax_kobo bigint,sourcing text,availability_at_creation text);\n insert into hardware_order_events(order_id,event_type,row_version,actor,metadata) values(o.id,'created',1,p_actor,jsonb_build_object('currency','NGN','goods_total_kobo',total,'goods_tax_kobo',taxes,'payment_eligible',false));\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(p_actor,'hardware_order_created','hardware_order',o.id::text,jsonb_build_object('row_version',1,'line_count',pos,'payment_eligible',false));\n insert into crm_activities(contact_id,organization_id,opportunity_id,related_type,related_id,activity_type,title,source,actor,metadata) values(cid,oid,opid,'hardware_order',o.id::text,'hardware_order_created','Hardware order awaiting confirmation','office',p_actor,jsonb_build_object('order_id',o.id));\n return jsonb_build_object('id',o.id,'replayed',false);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_immutable()","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin raise exception 'order_history_immutable' using errcode='PT409'; end $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_require_actor(text,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_require_actor(p_actor text, p_permission text)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n if not exists(select 1 from admin_users where lower(email)=p_actor and status='active' and removed_at is null\n and role in ('super_admin','ochiga_admin','ochiga_staff') and (role='super_admin' or p_permission='crm.read' or p_permission=any(coalesce(permission_scopes,'{}')))) then\n raise exception 'forbidden' using errcode='PT403'; end if;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_order_state_guard()","definition":"CREATE OR REPLACE FUNCTION public.hardware_order_state_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$begin\n if tg_op='UPDATE' and (to_jsonb(new)-array['delivery_total_kobo','payable_total_kobo','delivery_state'])=(to_jsonb(old)-array['delivery_total_kobo','payable_total_kobo','delivery_state'])\n and old.delivery_state='unconfirmed' and new.delivery_state='confirmed' and new.payable_total_kobo=new.goods_total_kobo+new.delivery_total_kobo\n and exists(select 1 from hardware_payment_delivery d where d.order_id=new.id and d.gross_kobo=new.delivery_total_kobo) then return new;end if;\n if tg_op='UPDATE' and (to_jsonb(new)-'payment_state')=(to_jsonb(old)-'payment_state') and old.payment_state='not_started'\n and exists(select 1 from hardware_payment_confirmations c where c.order_id=new.id and c.outcome=new.payment_state) then return new;end if;\n if tg_op='UPDATE' and (to_jsonb(new)-array['reservation_state','fulfilment_state'])=(to_jsonb(old)-array['reservation_state','fulfilment_state'])\n and new.fulfilment_state=(case when new.reservation_state='allocated' then 'allocated' else 'unallocated' end)\n and ((old.reservation_state='not_reserved' and new.reservation_state='held') or (old.reservation_state='held' and new.reservation_state in ('released','expired','allocated'))) then return new;end if;\n if tg_op<>'UPDATE' or (to_jsonb(new)-array['order_state','row_version','updated_at']) is distinct from (to_jsonb(old)-array['order_state','row_version','updated_at'])\n or old.reservation_state='allocated' or old.order_state<>'awaiting_confirmation' or new.order_state<>'cancelled' or new.row_version<>old.row_version+1 then raise exception 'invalid_order_transition' using errcode='PT409';end if;return new;end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_authorize(text,text,uuid,bigint)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_authorize(p_client text, p_guest_hash text, p_order uuid, p_accepted_total bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare q jsonb;a hardware_payment_authorizations%rowtype;r hardware_reservations%rowtype;h text;begin\n q:=hardware_payment_quote(p_client,p_guest_hash,p_order);\n if (q->>'eligible')::boolean is distinct from true or (q->>'amount_kobo')::bigint is distinct from p_accepted_total then raise exception 'payment_not_eligible' using errcode='PT409';end if;\n select * into r from hardware_reservations where order_id=p_order;\n select * into a from hardware_payment_authorizations where order_id=p_order;\n if not found then\n h:=encode(sha256(convert_to(p_order::text||':'||r.id::text||':'||p_accepted_total::text||':NGN:test','UTF8')),'hex');\n insert into hardware_payment_authorizations values(p_order,'hwo_'||replace(p_order::text,'-',''),r.id,p_accepted_total,'NGN','test',h,now()) returning * into a;\n perform hardware_payment_log(p_order,'authorized','checkout:'||p_client,jsonb_build_object('reference',a.reference,'amount_kobo',a.amount_kobo));end if;\n return (to_jsonb(a)-'created_at')||jsonb_build_object('email',(select customer->>'email' from hardware_order_private where order_id=p_order));end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_confirm_delivery(text,uuid,bigint,bigint,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_confirm_delivery(p_actor text, p_order uuid, p_gross bigint, p_tax bigint, p_evidence text)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare d hardware_payment_delivery%rowtype;begin\n perform hardware_order_require_actor(p_actor,'commerce.orders.delivery.confirm');perform pg_advisory_xact_lock(71404,4);\n perform 1 from hardware_orders where id=p_order and order_state='awaiting_confirmation' and payment_state='not_started' for update;\n if not found then raise exception 'order_not_eligible' using errcode='PT409';end if;\n select * into d from hardware_payment_delivery where order_id=p_order;\n if found then if d.gross_kobo=p_gross and d.tax_kobo=p_tax and d.evidence=p_evidence then return;end if;raise exception 'delivery_already_confirmed' using errcode='PT409';end if;\n insert into hardware_payment_delivery values(p_order,p_gross,p_tax,p_actor,p_evidence,now());\n update hardware_orders set delivery_total_kobo=p_gross,payable_total_kobo=goods_total_kobo+p_gross,delivery_state='confirmed' where id=p_order;\n perform hardware_payment_log(p_order,'delivery_confirmed',p_actor,jsonb_build_object('gross_kobo',p_gross,'tax_kobo',p_tax));end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_confirm(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_confirm(p jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare a hardware_payment_authorizations%rowtype;c hardware_payment_confirmations%rowtype;o hardware_orders%rowtype;r hardware_reservations%rowtype;outcome text;begin\n perform pg_advisory_xact_lock(71404,4);\n select * into a from hardware_payment_authorizations where reference=p->>'reference';\n if not found then raise exception 'unknown_payment_reference' using errcode='PT404';end if;\n if p->>'order_id' is distinct from a.order_id::text or p->>'reservation_id' is distinct from a.reservation_id::text or p->>'amount_kobo' is distinct from a.amount_kobo::text or p->>'currency' is distinct from a.currency or p->>'environment' is distinct from a.environment or p->>'purpose' is distinct from 'hardware_order' or p->>'authorization_hash' is distinct from a.authorization_hash or coalesce(p->>'provider_id','') !~ '^[0-9]+$' then raise exception 'payment_evidence_mismatch' using errcode='PT409';end if;\n select * into c from hardware_payment_confirmations where reference=a.reference;\n if found then if c.provider_id<>p->>'provider_id' then raise exception 'duplicate_payment_requires_reconciliation' using errcode='PT409';end if;return jsonb_build_object('payment_state',c.outcome,'replayed',true);end if;\n select * into o from hardware_orders where id=a.order_id for update;select * into r from hardware_reservations where id=a.reservation_id for update;\n outcome:=case when o.order_state='awaiting_confirmation' and o.payment_state='not_started' and r.state='held' and r.expires_at>clock_timestamp() and hardware_payment_eligible(o.id) then 'paid' else 'refund_required' end;\n insert into hardware_payment_confirmations values(a.reference,p->>'provider_id',a.order_id,a.reservation_id,a.amount_kobo,a.currency,a.environment,a.authorization_hash,outcome,now());\n if outcome='paid' then if hardware_reservation_allocate(o.id)->>'state' is distinct from 'allocated' then raise exception 'reservation_expired_retry_confirmation' using errcode='PT409';end if;else perform hardware_reservation_finish(o.id,'released','payment','Payment requires refund');end if;\n update hardware_orders set payment_state=outcome where id=o.id;\n perform hardware_payment_log(o.id,outcome,'backend:hardware_payments',jsonb_build_object('reference',a.reference,'provider_id',p->>'provider_id'));\n insert into crm_activities(contact_id,opportunity_id,related_type,related_id,activity_type,title,source,actor,metadata) values(o.contact_id,o.opportunity_id,'hardware_order',o.id::text,'hardware_payment_'||outcome,'Hardware payment verified','backend','backend:hardware_payments',jsonb_build_object('payment_state',outcome));\n return jsonb_build_object('payment_state',outcome,'replayed',false);end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_consistency()","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_consistency()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare oid uuid;o hardware_orders%rowtype;c hardware_payment_confirmations%rowtype;a hardware_payment_authorizations%rowtype;begin\n oid:=coalesce((to_jsonb(new)->>'order_id')::uuid,(to_jsonb(new)->>'id')::uuid);select * into o from hardware_orders where id=oid;select * into c from hardware_payment_confirmations where order_id=oid;select * into a from hardware_payment_authorizations where order_id=oid;\n if (o.payment_state<>'not_started' and c.order_id is null) or (c.order_id is not null and (c.outcome<>o.payment_state or c.amount_kobo is distinct from o.payable_total_kobo or c.amount_kobo<>a.amount_kobo or c.authorization_hash<>a.authorization_hash or c.reservation_id<>a.reservation_id or (c.outcome='paid' and o.reservation_state<>'allocated') or not exists(select 1 from hardware_payment_history h where h.order_id=oid and h.event_type=c.outcome)))\n or (o.delivery_state='confirmed' and not exists(select 1 from hardware_payment_delivery d where d.order_id=oid and d.gross_kobo=o.delivery_total_kobo))\n or exists(select 1 from hardware_payment_history h where h.order_id=oid and not exists(select 1 from audit_events e where e.target_id=oid::text and e.action='hardware_payment_'||h.event_type and e.actor_email=h.actor)) then raise exception 'payment_integrity_violation' using errcode='PT409';end if;return null;end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_eligible(uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_eligible(p_order uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare l record;v catalogue_variants%rowtype;p catalogue_products%rowtype;begin\n perform cp.id from catalogue_products cp join hardware_order_lines ol on ol.product_id=cp.id where ol.order_id=p_order order by cp.id for share of cp;\n for l in select * from hardware_order_lines where order_id=p_order order by variant_id loop\n select * into v from catalogue_variants where id=l.variant_id for share;\n select * into p from catalogue_products where id=l.product_id;\n perform 1 from catalogue_public_listings where product_id=p.id and status='public' and public_version=l.product_version for share;\n if not found or p.publication_status<>'published' or p.published_version<>l.product_version or v.status<>'active' or v.sourcing<>'in_stock' or v.stock_reserved<l.quantity or v.stock_on_hand<v.stock_reserved or v.price_ngn_kobo<>l.unit_price_kobo or v.vat_rate_bp<>l.vat_rate_bp or v.vat_treatment<>l.vat_treatment\n or not exists(select 1 from catalogue_price_changes c where c.id=l.price_change_id and c.new_price_ngn_kobo=v.price_ngn_kobo and exists(select 1 from catalogue_price_decisions x where x.price_change_id=c.id and x.decision='approved' and x.actor<>c.requested_by) and exists(select 1 from catalogue_price_decisions x where x.price_change_id=c.id and x.decision='published')) then return false;end if;\n end loop;return exists(select 1 from hardware_order_lines where order_id=p_order);end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_log(uuid,text,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_log(p_order uuid, p_event text, p_actor text, p_detail jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$begin\n insert into hardware_payment_history(order_id,event_type,actor,detail) values(p_order,p_event,p_actor,p_detail);\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(p_actor,'hardware_payment_'||p_event,'hardware_order',p_order::text,p_detail);\nend$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_previous_order_guard()","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_previous_order_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n if tg_op='UPDATE' and (to_jsonb(new)-array['reservation_state','fulfilment_state'])=(to_jsonb(old)-array['reservation_state','fulfilment_state'])\n and new.fulfilment_state=(case when new.reservation_state='allocated' then 'allocated' else 'unallocated' end)\n and ((old.reservation_state='not_reserved' and new.reservation_state='held') or (old.reservation_state='held' and new.reservation_state in ('released','expired','allocated'))) then return new;end if;\n if tg_op<>'UPDATE' then raise exception 'order_history_immutable' using errcode='PT409';end if;\n if (to_jsonb(new)-array['order_state','row_version','updated_at']) is distinct from (to_jsonb(old)-array['order_state','row_version','updated_at'])\n or old.reservation_state='allocated' or old.order_state<>'awaiting_confirmation' or new.order_state<>'cancelled' or new.row_version<>old.row_version+1 then raise exception 'invalid_order_transition' using errcode='PT409';end if;\n return new;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_payment_quote(text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_payment_quote(p_client text, p_guest_hash text, p_order uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare q jsonb;s text;begin\n q:=hardware_financial_previous_quote(p_client,p_guest_hash,p_order);\n select state into s from hardware_financial_observations where order_id=p_order and state like 'refund_%' order by case when state='refund_processed' then 0 else 1 end,event_id desc limit 1;\n return q||jsonb_build_object('refund_state',s);end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_refund_approve(text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_refund_approve(p_actor text, p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare r hardware_refund_requests%rowtype;d hardware_refund_decisions%rowtype;begin\n perform hardware_order_require_actor(p_actor,'commerce.orders.refund.approve');select * into r from hardware_refund_requests where id=p_id for update;\n if not found then raise exception 'refund_not_found' using errcode='PT404';end if;\n if p_actor=r.requested_by then raise exception 'self_approval_denied' using errcode='PT403';end if;\n if exists(select 1 from hardware_financial_observations where order_id=r.order_id and state in ('disputed','dispute_review','reversed_unreconciled','amount_mismatch')) then raise exception 'manual_reconciliation_required' using errcode='PT409';end if;\n select * into d from hardware_refund_decisions where request_id=p_id;\n if found then if d.approved_by<>p_actor then raise exception 'refund_already_approved' using errcode='PT409';end if;return to_jsonb(d);end if;\n insert into hardware_refund_decisions values(p_id,p_actor,now()) returning * into d;\n perform hardware_payment_log(r.order_id,'refund_approved',p_actor,jsonb_build_object('request_id',r.id));return to_jsonb(d);end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_refund_approved()","definition":"CREATE OR REPLACE FUNCTION public.hardware_refund_approved()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO 'public', 'pg_temp'\nAS $function$select coalesce(jsonb_agg(jsonb_build_object('approval_id',r.id,'order_id',r.order_id,'reference',r.reference,'amount_kobo',r.amount_kobo,'requested_by',r.requested_by,'approved_by',d.approved_by)),'[]') from hardware_refund_requests r join hardware_refund_decisions d on d.request_id=r.id where not exists(select 1 from hardware_financial_observations f where f.order_id=r.order_id and f.state='refund_processed')$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_refund_request(text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_refund_request(p_actor text, p_order uuid, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$declare c hardware_payment_confirmations%rowtype;r hardware_refund_requests%rowtype;begin\n perform hardware_order_require_actor(p_actor,'commerce.orders.refund.request');\n select * into c from hardware_payment_confirmations where order_id=p_order for update;\n if not found then raise exception 'verified_payment_required' using errcode='PT409';end if;\n select * into r from hardware_refund_requests where order_id=p_order;\n if found then if r.requested_by<>p_actor or r.reason<>p_reason then raise exception 'refund_request_conflict' using errcode='PT409';end if;return to_jsonb(r);end if;\n insert into hardware_refund_requests(order_id,reference,amount_kobo,requested_by,reason) values(p_order,c.reference,c.amount_kobo,p_actor,p_reason) returning * into r;\n perform hardware_payment_log(p_order,'refund_requested',p_actor,jsonb_build_object('request_id',r.id,'amount_kobo',r.amount_kobo));\n return to_jsonb(r);end$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_allocate(uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_allocate(p_order uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare r hardware_reservations%rowtype;\nbegin\n perform pg_advisory_xact_lock(71404,4);\n perform 1 from hardware_orders where id=p_order for update;\n select * into r from hardware_reservations where order_id=p_order for update;\n if not found then raise exception 'reservation_not_found' using errcode='PT404';end if;\n if r.state='allocated' then return jsonb_build_object('id',r.id,'state','allocated','replayed',true);end if;\n if r.state<>'held' then raise exception 'reservation_not_held' using errcode='PT409';end if;\n if r.expires_at<=clock_timestamp() then return hardware_reservation_finish(p_order,'expired','system:reservation-expiry','Payment arrived after expiry');end if;\n if not hardware_reservation_payment_verified(p_order,r.id) then raise exception 'verified_order_payment_required' using errcode='PT409';end if;\n return hardware_reservation_finish(p_order,'allocated','system:verified-order-payment','Verified order payment allocation');\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_cancel_core(text,uuid,integer)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_cancel_core(p_actor text, p_id uuid, p_expected integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare o hardware_orders%rowtype;\nbegin\n perform hardware_order_require_actor(p_actor,'commerce.orders.cancel');\n select * into o from hardware_orders where id=p_id for update;\n if not found then raise exception 'order_not_found' using errcode='PT404'; end if;\n if o.order_state='cancelled' and o.row_version=p_expected+1 then return jsonb_build_object('id',o.id,'row_version',o.row_version,'order_state',o.order_state,'replayed',true); end if;\n if o.reservation_state='allocated' then raise exception 'allocated_order_requires_refund_workflow' using errcode='PT409';end if;\n if o.row_version<>p_expected or o.order_state<>'awaiting_confirmation' then raise exception 'order_state_changed' using errcode='PT409'; end if;\n update hardware_orders set order_state='cancelled',row_version=row_version+1,updated_at=now() where id=p_id returning * into o;\n insert into hardware_order_events(order_id,event_type,row_version,actor) values(o.id,'cancelled',o.row_version,p_actor);\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(p_actor,'hardware_order_cancelled','hardware_order',o.id::text,jsonb_build_object('row_version',o.row_version));\n insert into crm_activities(contact_id,organization_id,opportunity_id,related_type,related_id,activity_type,title,source,actor,metadata) values(o.contact_id,o.organization_id,o.opportunity_id,'hardware_order',o.id::text,'hardware_order_cancelled','Hardware order cancelled','office',p_actor,jsonb_build_object('order_id',o.id));\n return jsonb_build_object('id',o.id,'row_version',o.row_version,'order_state',o.order_state);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_check()","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_check()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare r hardware_reservations%rowtype; o hardware_orders%rowtype; rid uuid; vid uuid; baseline integer; held bigint;\nbegin\n if tg_table_name in ('catalogue_variants','hardware_reservation_stock') then\n vid:=coalesce((to_jsonb(new)->>'variant_id')::uuid,(to_jsonb(new)->>'id')::uuid);\n select legacy_reserved into baseline from hardware_reservation_stock where variant_id=vid;\n if found then\n select coalesce(sum(l.quantity),0) into held from hardware_reservation_lines l join hardware_reservations x on x.id=l.reservation_id where l.variant_id=vid and x.state='held';\n if not exists(select 1 from catalogue_variants where id=vid and stock_reserved=baseline+held) then raise exception 'reservation_stock_integrity' using errcode='PT409';end if;\n end if;return null;end if;\n if tg_table_name='hardware_orders' then\n select * into r from hardware_reservations where order_id=new.id;\n if not found then if new.reservation_state<>'not_reserved' then raise exception 'reservation_order_integrity' using errcode='PT409';end if;return null;end if;\n else rid:=coalesce((to_jsonb(new)->>'reservation_id')::uuid,(to_jsonb(new)->>'id')::uuid);select * into r from hardware_reservations where id=rid;end if;\n select * into o from hardware_orders where id=r.order_id;\n if o.reservation_state<>r.state or (o.order_state='cancelled' and r.state='held')\n or (r.state='allocated' and (o.fulfilment_state<>'allocated' or not hardware_reservation_payment_verified(o.id,r.id)))\n or (r.state<>'allocated' and o.fulfilment_state<>'unallocated')\n or not exists(select 1 from hardware_reservation_events where reservation_id=r.id and row_version=1 and event_type='held' and actor=r.actor)\n or (select count(*) from hardware_reservation_events where reservation_id=r.id)<>r.row_version\n or not exists(select 1 from hardware_reservation_events where reservation_id=r.id and row_version=r.row_version and event_type=r.state)\n or exists((select variant_id,quantity from hardware_order_lines where order_id=o.id) except (select variant_id,quantity from hardware_reservation_lines where reservation_id=r.id))\n or exists((select variant_id,quantity from hardware_reservation_lines where reservation_id=r.id) except (select variant_id,quantity from hardware_order_lines where order_id=o.id))\n or exists(select 1 from hardware_reservation_events e where e.reservation_id=r.id and not exists(select 1 from audit_events a where a.target_type='hardware_reservation' and a.target_id=r.id::text and a.action='hardware_reservation_'||e.event_type and a.actor_email=e.actor and a.metadata->>'row_version'=e.row_version::text))\n or exists(select 1 from hardware_reservation_lines l join hardware_reservation_events e on e.reservation_id=l.reservation_id where l.reservation_id=r.id and not exists(select 1 from catalogue_inventory_changes c where c.variant_id=l.variant_id and c.field='stock_reserved' and c.reason='reservation:'||r.id::text||':'||e.row_version and c.actor=e.actor and (c.new_value::integer-c.old_value::integer)=case when e.event_type='held' then l.quantity else -l.quantity end))\n or exists(select 1 from hardware_reservation_lines l where l.reservation_id=r.id and r.state='allocated' and not exists(select 1 from catalogue_inventory_changes c where c.variant_id=l.variant_id and c.field='stock_on_hand' and c.reason='reservation:'||r.id::text||':2' and c.new_value::integer-c.old_value::integer=-l.quantity))\n then raise exception 'reservation_integrity' using errcode='PT409';end if;\n return null;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_checkout(text,text,text,jsonb,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_checkout(p_client text, p_guest_hash text, p_key text, p_request jsonb, p_quote_hash text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare result jsonb; hold jsonb;\nbegin\n perform pg_advisory_xact_lock(71404,4);perform hardware_reservation_expire(1000);\n result:=hardware_checkout_submit(p_client,p_guest_hash,p_key,p_request,p_quote_hash);\n hold:=hardware_reservation_hold((result->>'id')::uuid,p_key,'checkout:'||p_client,900);\n return result||jsonb_build_object('reservation',hold,'payment_eligible',false);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_expire(integer)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_expire(p_limit integer DEFAULT 500)\n RETURNS integer\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare r record; n integer:=0;\nbegin\n if p_limit not between 1 and 1000 then raise exception 'invalid_limit' using errcode='PT400';end if;\n perform pg_advisory_xact_lock(71404,4);\n for r in select order_id from hardware_reservations where state='held' and expires_at<=clock_timestamp() order by expires_at,id limit p_limit loop\n perform hardware_reservation_finish(r.order_id,'expired','system:reservation-expiry','Reservation TTL elapsed');n:=n+1;end loop;\n return n;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_finish(uuid,text,text,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_finish(p_order uuid, p_state text, p_actor text, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare r hardware_reservations%rowtype; l record; before_qty integer; before_on_hand integer;\nbegin\n perform pg_advisory_xact_lock(71404,4);\n perform 1 from hardware_orders where id=p_order for update;\n select * into r from hardware_reservations where order_id=p_order for update;\n if not found then return jsonb_build_object('state','not_reserved');end if;\n if r.state<>'held' then return jsonb_build_object('id',r.id,'state',r.state,'replayed',true);end if;\n if p_state not in ('released','expired','allocated') then raise exception 'invalid_reservation_action' using errcode='PT400';end if;\n if p_state='allocated' and (r.expires_at<=clock_timestamp() or not hardware_reservation_payment_verified(p_order,r.id)) then raise exception 'verified_order_payment_required' using errcode='PT409';end if;\n if p_state='expired' and r.expires_at>clock_timestamp() then raise exception 'reservation_not_expired' using errcode='PT409';end if;\n if r.expires_at<=clock_timestamp() then p_state:='expired';end if;\n for l in select * from hardware_reservation_lines where reservation_id=r.id order by variant_id loop\n select stock_reserved,stock_on_hand into before_qty,before_on_hand from catalogue_variants where id=l.variant_id for update;\n update catalogue_variants set stock_reserved=stock_reserved-l.quantity,stock_on_hand=stock_on_hand-case when p_state='allocated' then l.quantity else 0 end,row_version=row_version+1,updated_at=now() where id=l.variant_id;\n insert into catalogue_inventory_changes(variant_id,field,old_value,new_value,actor,reason) values(l.variant_id,'stock_reserved',before_qty::text,(before_qty-l.quantity)::text,p_actor,'reservation:'||r.id::text||':2');\n if p_state='allocated' then insert into catalogue_inventory_changes(variant_id,field,old_value,new_value,actor,reason) values(l.variant_id,'stock_on_hand',before_on_hand::text,(before_on_hand-l.quantity)::text,p_actor,'reservation:'||r.id::text||':2');end if;\n end loop;\n update hardware_reservations set state=p_state,ended_at=clock_timestamp(),row_version=2 where id=r.id;\n update hardware_orders set reservation_state=p_state,fulfilment_state=case when p_state='allocated' then 'allocated' else 'unallocated' end where id=p_order;\n insert into hardware_reservation_events(reservation_id,row_version,event_type,actor,reason) values(r.id,2,p_state,p_actor,left(coalesce(p_reason,''),500));\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(p_actor,'hardware_reservation_'||p_state,'hardware_reservation',r.id::text,jsonb_build_object('order_id',p_order,'row_version',2));\n return jsonb_build_object('id',r.id,'state',p_state,'replayed',false);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_guard()","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n if tg_op<>'UPDATE' or old.state<>'held' or new.state not in ('released','expired','allocated') or new.row_version<>old.row_version+1\n or new.ended_at is null or (to_jsonb(new)-array['state','row_version','ended_at']) is distinct from (to_jsonb(old)-array['state','row_version','ended_at'])\n then raise exception 'reservation_history_immutable' using errcode='PT409';end if;\n return new;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_hold(uuid,text,text,integer)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_hold(p_order uuid, p_key text, p_actor text, p_ttl integer DEFAULT 900)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare o hardware_orders%rowtype; r hardware_reservations%rowtype; l record; q jsonb; current_line jsonb; h text; old_qty integer;\nbegin\n if p_key is null or p_key !~ '^[A-Za-z0-9_-]{16,128}$' or p_ttl not between 60 and 1800 then raise exception 'invalid_reservation' using errcode='PT400';end if;\n perform pg_advisory_xact_lock(71404,4);\n perform hardware_reservation_expire(1000);\n select * into o from hardware_orders where id=p_order for update;\n if not found then raise exception 'order_not_found' using errcode='PT404';end if;\n h:=encode(sha256(convert_to(p_order::text||':'||p_ttl::text,'UTF8')),'hex');\n select * into r from hardware_reservations where order_id=p_order;\n if found then\n if r.idempotency_key<>p_key or r.request_hash<>h then raise exception 'idempotency_conflict' using errcode='PT409';end if;\n return jsonb_build_object('id',r.id,'state',r.state,'expires_at',r.expires_at,'replayed',true);end if;\n if o.order_state<>'awaiting_confirmation' or o.payment_state<>'not_started' or o.reservation_state<>'not_reserved' then raise exception 'order_not_eligible' using errcode='PT409';end if;\n -- Quote checks independently approved price, current public version, sourcing and quantities under product/variant locks.\n select jsonb_agg(jsonb_build_object('variant_id',variant_id,'quantity',quantity) order by variant_id) into q from hardware_order_lines where order_id=p_order;\n q:=hardware_checkout_quote(q);\n for l in select * from hardware_order_lines where order_id=p_order order by variant_id loop\n select x into current_line from jsonb_array_elements(q->'lines') x where x->>'variant_id'=l.variant_id::text;\n if current_line->>'product_version'<>l.product_version::text or current_line->>'unit_price_kobo'<>l.unit_price_kobo::text or current_line->>'vat_rate_bp'<>l.vat_rate_bp::text or current_line->>'vat_treatment'<>l.vat_treatment or current_line->>'price_change_id'<>l.price_change_id::text then raise exception 'order_price_changed' using errcode='PT409';end if;\n end loop;\n -- Upgrade locks in the same stable order. A single DB mutex prevents shared-lock upgrade races between reservations.\n perform v.id from catalogue_variants v join hardware_order_lines ol on ol.variant_id=v.id where ol.order_id=p_order order by v.id for update of v;\n insert into hardware_reservations(order_id,idempotency_key,request_hash,actor,expires_at) values(p_order,p_key,h,p_actor,clock_timestamp()+make_interval(secs=>p_ttl)) returning * into r;\n for l in select * from hardware_order_lines where order_id=p_order order by variant_id loop\n select stock_reserved into old_qty from catalogue_variants where id=l.variant_id;\n insert into hardware_reservation_stock values(l.variant_id,old_qty) on conflict do nothing;\n insert into hardware_reservation_lines values(r.id,l.variant_id,l.quantity);\n update catalogue_variants set stock_reserved=stock_reserved+l.quantity,row_version=row_version+1,updated_at=now() where id=l.variant_id and stock_on_hand-stock_reserved>=l.quantity;\n if not found then raise exception 'stock_unavailable' using errcode='PT409';end if;\n insert into catalogue_inventory_changes(variant_id,field,old_value,new_value,actor,reason) values(l.variant_id,'stock_reserved',old_qty::text,(old_qty+l.quantity)::text,p_actor,'reservation:'||r.id::text||':1');\n end loop;\n update hardware_orders set reservation_state='held' where id=p_order;\n insert into hardware_reservation_events(reservation_id,row_version,event_type,actor) values(r.id,1,'held',p_actor);\n insert into audit_events(actor_email,action,target_type,target_id,metadata) values(p_actor,'hardware_reservation_held','hardware_reservation',r.id::text,jsonb_build_object('order_id',p_order,'row_version',1,'expires_at',r.expires_at));\n return jsonb_build_object('id',r.id,'state','held','expires_at',r.expires_at,'replayed',false);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_inventory_core(uuid,integer,jsonb,text,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_inventory_core(p_variant_id uuid, p_expected_row_version integer, p_patch jsonb, p_actor text, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare o catalogue_variants%rowtype; v catalogue_variants%rowtype; f text;\nbegin\n  select * into o from catalogue_variants where id = p_variant_id and row_version = p_expected_row_version for update;\n  if not found then\n    if not exists (select 1 from catalogue_variants where id = p_variant_id) then raise exception 'variant_not_found' using errcode = 'PT404'; end if;\n    raise exception 'state_changed' using errcode = 'PT409', detail = (select jsonb_build_object('id', id, 'row_version', row_version) from catalogue_variants where id = p_variant_id)::text;\n  end if;\n  update catalogue_variants set\n    stock_on_hand = case when p_patch ? 'stock_on_hand' then (p_patch->>'stock_on_hand')::integer else stock_on_hand end,\n    stock_reserved = case when p_patch ? 'stock_reserved' then (p_patch->>'stock_reserved')::integer else stock_reserved end,\n    sourcing = case when p_patch ? 'sourcing' then p_patch->>'sourcing' else sourcing end,\n    lead_time_days_min = case when p_patch ? 'lead_time_days_min' then (p_patch->>'lead_time_days_min')::integer else lead_time_days_min end,\n    lead_time_days_max = case when p_patch ? 'lead_time_days_max' then (p_patch->>'lead_time_days_max')::integer else lead_time_days_max end,\n    status = case when p_patch ? 'status' then p_patch->>'status' else status end,\n    supplier_id = case when p_patch ? 'supplier_id' then nullif(p_patch->>'supplier_id', '') else supplier_id end,\n    row_version = row_version + 1, updated_at = now()\n  where id = p_variant_id and row_version = p_expected_row_version\n  returning * into v;\n  foreach f in array array['stock_on_hand', 'stock_reserved', 'sourcing', 'lead_time_days_min', 'lead_time_days_max', 'status', 'supplier_id'] loop\n    if (to_jsonb(o)->>f) is distinct from (to_jsonb(v)->>f) then\n      insert into catalogue_inventory_changes (variant_id, field, old_value, new_value, actor, reason) values (v.id, f, to_jsonb(o)->>f, to_jsonb(v)->>f, p_actor, coalesce(p_reason, ''));\n    end if;\n  end loop;\n  return to_jsonb(v);\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_payment_verified(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_payment_verified(p_order uuid, p_reservation uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO 'public', 'pg_temp'\nAS $function$\n select exists(select 1 from hardware_payment_confirmations c join hardware_payment_authorizations a using(reference) join hardware_orders o on o.id=c.order_id where c.order_id=p_order and c.reservation_id=p_reservation and c.outcome='paid' and c.amount_kobo=a.amount_kobo and c.amount_kobo=o.payable_total_kobo and c.authorization_hash=a.authorization_hash and c.environment='test' and c.currency='NGN' and o.delivery_state='confirmed')$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_staff(text,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_staff(p_actor text, p_order uuid, p_key text, p_action text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n perform hardware_order_require_actor(p_actor,'commerce.orders.read');\n if p_action='hold' then perform hardware_order_require_actor(p_actor,'commerce.orders.create');return hardware_reservation_hold(p_order,p_key,p_actor,900);\n elsif p_action='release' then perform hardware_order_require_actor(p_actor,'commerce.orders.cancel');return hardware_reservation_finish(p_order,'released',p_actor,'Staff release');\n else raise exception 'invalid_reservation_action' using errcode='PT400';end if;\nend $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"hardware_reservation_status(text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.hardware_reservation_status(p_client text, p_guest_hash text, p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare result jsonb; reservation jsonb;\nbegin\n result:=hardware_checkout_get(p_client,p_guest_hash,p_id);if result is null then return null;end if;\n perform hardware_reservation_expire(1000);\n select jsonb_build_object('id',id,'state',state,'expires_at',expires_at) into reservation from hardware_reservations where order_id=p_id;\n return result||jsonb_build_object('reservation',reservation);\nend $function$\n"}],"relations":[{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false],["service_role","DELETE",false],["service_role","INSERT",false],["service_role","SELECT",false],["service_role","UPDATE",false]],"rls":true,"kind":"r","name":"hardware_checkout_receipts","owner":"postgres","columns":[{"acl":null,"name":"client","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"guest_hash","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"idempotency_key","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"request_hash","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"policies":0,"triggers":[["checkout_receipts_immutable","CREATE TRIGGER checkout_receipts_immutable BEFORE DELETE OR UPDATE ON public.hardware_checkout_receipts FOR EACH ROW EXECUTE FUNCTION hardware_order_immutable()","O"],["checkout_receipts_no_truncate","CREATE TRIGGER checkout_receipts_no_truncate BEFORE TRUNCATE ON public.hardware_checkout_receipts FOR EACH STATEMENT EXECUTE FUNCTION hardware_order_immutable()","O"]],"force_rls":false,"constraints":[["hardware_checkout_receipts_guest_hash_check","CHECK ((guest_hash ~ '^[0-9a-f]{64}$'::text))",true,false,false],["hardware_checkout_receipts_order_id_fkey","FOREIGN KEY (order_id) REFERENCES hardware_orders(id) ON DELETE RESTRICT",true,false,false],["hardware_checkout_receipts_order_id_key","UNIQUE (order_id)",true,false,false],["hardware_checkout_receipts_pkey","PRIMARY KEY (client, guest_hash, idempotency_key)",true,false,false]]},{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false]],"rls":false,"kind":"i","name":"hardware_checkout_receipts_order_id_key","owner":"postgres","columns":[{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":false,"generated":""}],"policies":0,"triggers":[],"force_rls":false,"constraints":[]},{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false]],"rls":false,"kind":"i","name":"hardware_checkout_receipts_pkey","owner":"postgres","columns":[{"acl":null,"name":"client","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"guest_hash","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"idempotency_key","type":"text","default":null,"identity":"","not_null":false,"generated":""}],"policies":0,"triggers":[],"force_rls":false,"constraints":[]},{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false],["service_role","INSERT",false],["service_role","SELECT",false]],"rls":true,"kind":"r","name":"hardware_financial_observations","owner":"postgres","columns":[{"acl":null,"name":"event_id","type":"bigint","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"reference","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"state","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"evidence","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"fingerprint","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"policies":0,"triggers":[["financial_immutable","CREATE TRIGGER financial_immutable BEFORE DELETE OR UPDATE ON public.hardware_financial_observations FOR EACH ROW EXECUTE FUNCTION hardware_order_immutable()","O"],["financial_no_truncate","CREATE TRIGGER financial_no_truncate BEFORE TRUNCATE ON public.hardware_financial_observations FOR EACH STATEMENT EXECUTE FUNCTION hardware_order_immutable()","O"]],"force_rls":false,"constraints":[["hardware_financial_observations_order_id_fkey","FOREIGN KEY (order_id) REFERENCES hardware_orders(id)",true,false,false],["hardware_financial_observations_pkey","PRIMARY KEY (event_id)",true,false,false],["hardware_financial_observations_reference_fkey","FOREIGN KEY (reference) REFERENCES hardware_payment_authorizations(reference)",true,false,false],["hardware_financial_observations_state_check","CHECK ((state = ANY (ARRAY['provider_pending'::text, 'pending_overdue'::text, 'provider_failed'::text, 'provider_unavailable'::text, 'p